UPDATE alphafrog_agent_run_recovery_notification SET
    next_visible_at = #{nextVisibleAt},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{notificationId}
  AND state = 'WAITING'
  AND next_visible_at < #{nextVisibleAt}

mapper.select:
WITH member_input AS (
    SELECT *
    FROM (VALUES

        (#{m.memberSeq}::int, #{m.memberIdentity}::varchar, #{m.toolCallId}::varchar,
         #{m.toolName}::varchar, #{m.externalOperationId}::varchar)

    ) AS m(member_seq, member_identity, tool_call_id, tool_name, external_operation_id)
),
run_fence AS (
    SELECT r.id AS run_id, r.plan_generation, r.run_control_version
    FROM alphafrog_agent_run r
    WHERE r.id = #{runId}
      AND r.status = 'EXECUTING'
      -- 计划代际与控制版本都在这里比对：计划推进之后控制版本可能还没变，只比控制版本
      -- 会让旧计划的执行者把已经作废的分段交出去、建出没人认领的等待组。
      AND r.plan_generation = #{planGeneration}
      -- 冻结的调度器版本也要对上：这份等待事实只属于等待组那一套执行层。
      AND r.scheduler_version = #{schedulerVersion}
      AND r.run_control_version = #{runControlVersion}
    FOR UPDATE
),
segment_closed AS (
    UPDATE alphafrog_agent_run_work_item wi SET
        state = 'RESULT_COMMITTED',
        claimed_by = NULL,
        lease_expires_at = NULL,
        payload_json = wi.payload_json || CAST(#{suspensionPayloadJson} AS jsonb),
        updated_at = CURRENT_TIMESTAMP
    WHERE wi.run_id = #{runId}
      AND wi.plan_generation = #{planGeneration}
      AND wi.node_id = #{nodeId}
      AND wi.node_attempt = #{nodeAttempt}
      AND wi.segment_sequence = #{segmentSequence}
      AND wi.state = 'EXECUTING'
      AND wi.claim_epoch = #{claimEpoch}
      AND wi.claimed_by = #{claimedBy}
      AND wi.context_version = #{contextVersion}
      AND wi.run_control_version = #{runControlVersion}
      AND EXISTS (SELECT 1 FROM run_fence)
    RETURNING wi.run_id, wi.plan_generation, wi.node_id, wi.node_attempt, wi.segment_sequence
),
group_created AS (
    INSERT INTO alphafrog_agent_run_wait_group
        (run_id, plan_generation, node_id, node_attempt, segment_sequence, model_turn,
         scheduler_version, next_segment_sequence, state, expected_members, completed_members)
    SELECT s.run_id, s.plan_generation, s.node_id, s.node_attempt, s.segment_sequence,
           #{modelTurn}::int, #{schedulerVersion}::varchar, s.segment_sequence + 1,
           'WAITING', (SELECT count(*) FROM member_input)::int, 0
    FROM segment_closed s
    RETURNING id, run_id, plan_generation, node_id, node_attempt, segment_sequence,
              next_segment_sequence
),
members_written AS (
    INSERT INTO alphafrog_agent_run_wait_member
        (group_id, run_id, member_seq, member_identity, tool_call_id, tool_name,
         external_operation_id, state)
    SELECT g.id, g.run_id, m.member_seq, m.member_identity, m.tool_call_id, m.tool_name,
           m.external_operation_id, 'PENDING'
    FROM group_created g
    CROSS JOIN member_input m
    RETURNING 1
),
next_segment_created AS (
    INSERT INTO alphafrog_agent_run_work_item
        (run_id, plan_generation, node_id, node_attempt, segment_sequence, state,
         context_version, run_control_version, claim_epoch, scheduler_version,
         next_visible_at, runnable_since, payload_json)
    SELECT g.run_id, g.plan_generation, g.node_id, g.node_attempt, g.next_segment_sequence,
           'WAITING', #{contextVersion}::bigint, #{runControlVersion}::bigint, 0,
           #{schedulerVersion}::varchar, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
           CAST(#{nextSegmentPayloadJson} AS jsonb)
    FROM group_created g
    RETURNING 1
)
SELECT
    (SELECT count(*) FROM segment_closed) AS closed_segments,
    (SELECT id FROM group_created) AS created_group_id,
    -- 读回已有的组也要过同一道 Run 栅栏：计划已经推进之后，旧工人重试同一个身份
    -- 读到的是一份作废的组，把它当成「已经挂起过」就会让执行者以为分段交出去了。
    (SELECT g.id FROM alphafrog_agent_run_wait_group g
      JOIN run_fence f ON f.run_id = g.run_id
      WHERE g.run_id = #{runId}
        AND g.plan_generation = #{planGeneration}
        AND g.node_id = #{nodeId}
        AND g.node_attempt = #{nodeAttempt}
        AND g.segment_sequence = #{segmentSequence}
        AND g.model_turn = #{modelTurn}) AS existing_group_id,
    (SELECT count(*) FROM members_written) AS written_members,
    (SELECT count(*) FROM next_segment_created) AS written_next_segments,
    -- 首次挂起时这一行是刚插进去的，同一条语句的主查询看不到它（数据修改 CTE 与主查询
    -- 用同一份快照），只能从 group_created 的 RETURNING 里取；幂等重试路径没有新插入，
    -- 才回基础表里读已经存在的组。
    COALESCE(
        (SELECT next_segment_sequence FROM group_created),
        (SELECT g.next_segment_sequence FROM alphafrog_agent_run_wait_group g
          JOIN run_fence f ON f.run_id = g.run_id
          WHERE g.run_id = #{runId}
            AND g.plan_generation = #{planGeneration}
            AND g.node_id = #{nodeId}
            AND g.node_attempt = #{nodeAttempt}
            AND g.segment_sequence = #{segmentSequence}
            AND g.model_turn = #{modelTurn})
    ) AS next_segment_sequence

