UPDATE alphafrog_agent_run_wait_member SET
    next_poll_at = #{nextPollAt},
    updated_at = CURRENT_TIMESTAMP
WHERE group_id = #{groupId}
  AND member_identity = #{memberIdentity}
  AND state = 'RUNNING'
